41	
42	export const EVIDENCE_DIRECTORY = path.join(
43		repositoryRoot,
44		'evidence/runs/angular-super-productivity-v2-13-15',
45	);
46	
47	export const UNIT = 'lrapr-t006/u18-super-productivity-migration-lanes';
48	export const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
