62	
63	/**
64	 * What the ingest's single green build did and did not settle, restated here so
65	 * a reader does not have to go and find it.
66	 */
67	export const ERA_VARIANT =
68		"The repository's own `buildFrontend` command — `node --max_old_space_size=4096 ./node_modules/@angular/cli/bin/ng build --aot --prod` — with its `yarn preCheck` (lint plus unit tests) prefix omitted, so that this measures a build and not a test run. The Electron sidecar that the manifest names as its `main` entry point is out of build scope and was never invoked on either lane. The production configuration this command selects turns on `serviceWorker`, so ngsw-worker.js, safety-worker.js and a generated ngsw.json are part of the emitted inventory, and `webWorkerTsConfig` compiles the two application web workers (lz, reminder) as separate chunks.";
69	
70	export const ERA_NOT_ESTABLISHED: readonly string[] = Object.freeze([
71		'Two consecutive builds on one host measure repeatability, not reproducibility. Nothing here establishes what another host, another day or another clock would emit — and on this fixture the same host on the same day already disagreed with itself.',
72		'No browser opened these bundles. Nothing about their behaviour, boot or runtime correctness is observed.',
73		'The ingest recorded this application as installing frozen and building green on the first attempt with zero deviations. That remains true and is not contradicted here: a green build and a byte-stable build are different claims, and only the first one was ever made.',
74		'The Electron sidecar was not built, not run and not analysed. Its dependencies are declared in the same manifest and are carried into no claim here.',
75	]);
76	
77	export const RECORDED_RISKS: readonly string[] = Object.freeze([
78		'The emitted service worker prefetches https://fonts.googleapis.com/** and https://fonts.gstatic.com/** at runtime, as ngsw-config.json declares. No lane here made that request, so nothing is established about what happens when it fails or is blocked.',
79		'node-sass ^4.12.0 declares a postinstall that fetches or compiles a native binding. Both the ingest install and this lane ran with lifecycle scripts disabled; every .scss input still compiled and styles.css still emitted, so nothing in the build path required that binding. That is a reading of this build, not a general claim about node-sass.',
