96	/** One file that two consecutive builds of the same tree did not agree on. */
97	export type InstabilityFinding = Readonly<{
98		path: string;
99		observed: string;
100		cause: string;
101		consequential: boolean;
102	}>;
103	
104	/** Paths present in both inventories whose digests differ. */
105	export function differingPaths(
106		first: readonly DistEntry[],
107		second: readonly DistEntry[],
108	): readonly string[] {
109		const right = new Map(second.map((entry) => [entry.path, entry.sha256]));
110		const differing: string[] = [];
111		for (const entry of first) {
112			const other = right.get(entry.path);
113			if (other === undefined || other !== entry.sha256) differing.push(entry.path);
