125			unit: UNIT,
126			consentId: CONSENT,
127			result: input.first.length > 0 && stable ? 'byte-stable' : 'rebuilt-green-not-byte-stable',
128			cell: {
129				node: input.nodeVersion,
130				architecture: 'darwin-x64 executed on darwin-arm64 through Rosetta 2',
131				packageManager: 'yarn 1.21.1',
132				command: 'node --max_old_space_size=4096 ./node_modules/@angular/cli/bin/ng build --aot --prod',
133				builder: '@angular-devkit/build-angular:browser 0.803.4 over webpack 4',
134				compiler: 'pre-Ivy ViewEngine, AOT — enableIvy appears in none of the 967 blobs and Angular 8.2 defaults to ViewEngine',
135				honestLabel:
136					"repository-declared as to major. .travis.yml pins `node_js: '12'`, which is what this cell runs; the patch level 12.14.1 and yarn 1.21.1 are the ingest's era-consistent choices, because the repository declares neither. The yarn 1.22.11-and-later defect recorded by the ingest — newer yarn walks up the directory tree, finds the host monorepo's packageManager field and demands Corepack — is avoided by the same fix the ingest recorded, not re-discovered.",
137			},
138			source: {
139				repository: 'super-productivity/super-productivity',
140				commit: '2943c5c4f13c3ce4dece0abf4f9c39739dde4192',
141				cache: '.versionless/cache/angular-super-productivity-v2-13-15-baseline',
142				provenance:
143					'Restored in this checkout from the u16 ingest: the era dependency closure installed by `yarn install --frozen-lockfile --ignore-scripts --non-interactive` against the committed 466,548-byte yarn.lock, 1061 top-level entries, lockfile unmutated.',
144				variant: ERA_VARIANT,
145				deviation: 'none. Nothing was pinned, patched or worked around in either rebuild, and no source file was modified.',
146			},
147			builds: [
148				{ run: 2, status: 0, files: input.first.length, seconds: input.firstSeconds },
149				{
