171	/** Every `.ts` module below a directory, as workspace files. */
172	async function typescriptModulesBelow(directory: string, root: string): Promise<WorkspaceFile[]> {
173		const files: WorkspaceFile[] = [];
174		for (const entry of (await readdir(directory, { withFileTypes: true })).sort((left, right) =>
175			left.name < right.name ? -1 : 1,
176		)) {
