275	/**
276	 * Era facts of this fixture that the workspace migration has to carry across
277	 * the hop or declare it dropped. They are recorded by name because a changeset
278	 * that silently loses one of them would still look clean.
279	 */
280	export const ERA_WORKSPACE_FACTS: readonly string[] = Object.freeze([
281		'ngsw-config.json plus the production `serviceWorker: true` option: the era build emits ngsw-worker.js, safety-worker.js and a generated ngsw.json, and the config file declares an external asset group that prefetches Google Fonts at runtime.',
282		'tsconfig.worker.json wired through the browser builder\'s `webWorkerTsConfig` option: two application web workers (lz, reminder) compile and emit as their own chunks in the era build.',
283		'`extractCss: true` on the production configuration — a valid key for the Angular 8 browser builder, and one the Angular 13 line removed.',
284		'A second workspace project, sp2-e2e, whose only targets are the protractor e2e runner and a TSLint lint target.',
285		'`cli.defaultCollection: "@ngrx/schematics"`, which names a schematics collection rather than a build input.',
286		'A `jo` devDependency declared as `file:./tools/schematics` — a workspace-local schematics package built by the repository\'s own `buildSchema` script.',
287	]);
